<?php if(!function_exists('account_change')){http_response_code(404);exit;} ?>
<section class="panel"><h2>Comptes internes Ogipen</h2><p>Ces comptes utilisent un mot de passe Ogipen, distinct de Windows/AD et du portail PHP. Les comptes admin et OSSI peuvent aussi recevoir des droits de projet, attribués séparément. Aucun rôle technique ne donne automatiquement le droit de modifier les câbles.</p>
<?php foreach($accountRows as $a):?><h3><?=h($a['login_name'])?> · <?=h($a['system_role'])?> · <?=$a['enabled']?'Actif':'Mot de passe à définir / désactivé'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="account_save"><input type="hidden" name="login" value="<?=h($a['login_name'])?>"><input type="hidden" name="revision" value="<?=h($a['auth_version'])?>"><?php account_fields($accountCompanies,$a);?><button>Enregistrer ce compte</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="account_disable"><input type="hidden" name="login" value="<?=h($a['login_name'])?>"><input type="hidden" name="revision" value="<?=h($a['auth_version'])?>"><button class="danger">Désactiver</button></form><?php endforeach;?></section>
<section class="panel"><h2>Créer un compte interne</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="account_save"><label>Login<input name="login" maxlength="80" required autocomplete="off" pattern="[A-Za-z0-9][A-Za-z0-9_.@-]{0,79}"></label><?php account_fields($accountCompanies,[]);?><button>Créer le compte</button></form></section>
<?php function account_fields(array $companies,array $a):void{?><div class="form-grid"><label>Nom affiché<input name="display_name" maxlength="180" required value="<?=h($a['display_name']??'')?>"></label><label>Entreprise<select name="company_id" required><?php foreach($companies as $c):?><option value="<?=h($c['id'])?>" <?=($a['company_id']??null)==$c['id']?'selected':''?>><?=h($c['display_name'])?></option><?php endforeach;?></select></label><label>Rôle technique<select name="system_role"><?php foreach(['user'=>'Utilisateur','admin'=>'Administrateur logiciel','ossi'=>'OSSI'] as $k=>$v):?><option value="<?=$k?>" <?=($a['system_role']??'user')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Droits du projet<select name="project_role"><?php $project=!empty($a['can_edit'])?'editor':(!empty($a['can_read'])?'reader':'none');foreach(['none'=>'Aucun accès métier','reader'=>'Lecture seule','editor'=>'Lecture et édition'] as $key=>$label):?><option value="<?=$key?>" <?=$key===$project?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div><label>Nouveau mot de passe (12 à 256 caractères ; vide pour conserver)<input type="password" name="new_password" minlength="12" maxlength="256" autocomplete="new-password" value=""></label><?php } ?>
